insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  'f34cbce3-32a7-4ac7-a974-0b977cb1d66c'::uuid,
  d.id,
  9,
  $d1ens9title$Mahishasura Mardini · A Stotram to Decode$d1ens9title$,
  $d1ens9json$["Dr Newton asked Harika to sing the stotram of Mahishasura Mardini. For everyone listening, it is homework. Tomorrow, when the story is taken up, it is to be decoded. If the hymn is taken only as praise, nothing of it is really known. Yogic secrets have been placed in it. Adi Shankaracharya composed it. The listening itself is the work: look at it two or three times, chant it, and find the meaning. In meditation a great deal becomes known.","Harika sang. The hymn opened with its first line, Ayi giri nandini nandita medini: O daughter of the mountain, delight of the earth. She carried it through to the close. While it was sung, a meditative state opened, and those who listened entered it. Among the knowledges Shankaracharya gave, this is one, and his description of that Shakti is finely made. The decoding remains the sadhaka's work. From there the morning opened into sharing."]$d1ens9json$::jsonb,
