insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  'c98bb0a9-bd22-468b-aed2-cebb94920855'::uuid,
  d.id,
  12,
  $d2ens12title$Mahishasura Mardini · Until Tomorrow$d2ens12title$,
  $d2ens12json$["He then asked Harika to let them hear the Mahishasura Mardini once more today. While she sings, the hymn can be received in a meditative state. The eyes may be closed, or they may stay open. Either way, the stotram is simply listened to.","Harika sang the Mahishasura Mardini Stotram through to its traditional close. It opens with the line, Ayi girinandini nanditamedini viśvavinodini nandinute. The inner meaning of her coming as Mahishasura Mardini had already been left for another day, when it would be decoded. Today the listening itself was the practice.","When the hymn ended, he thanked her. Such a divine experience, he said. Very profound.","Friends of Jnanodayam, we meet again tomorrow in the class. Surya was asked to share the slide, and the second day of Devi Navaratri came to its close."]$d2ens12json$::jsonb,
