insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  'f763c596-a07a-438f-a3bb-684301361fd2'::uuid,
  d.id,
  8,
  $d4ens8title$Halwa and the Lotus · Ramana and the Great Thief$d4ens8title$,
  $d4ens8json$["The one who wants liberation can still be caught. You want to eat halwa. You have taken sannyasa from it: I will not eat halwa. A sannyasa of halwa has been made. And it keeps pulling. Sit for meditation, and the first thing remembered is the halwa. The halwa even begins to appear. The experience of halwa comes. Whatever we exclude on the physical plane is included again. All of it returns, and in the practice it comes as an obstruction.","This is why the balance is needed, samsara and nirvana together. In samsara we are to be like a drop of water on a lotus leaf. The drop rests on the leaf, touching and not clinging. We are to live in samsara. We certainly are. If we only delight inside it, when will we delight in the field of the Atman? When will we be in that field? If we indulge only in the physical field, only here and only here, we forget the true goal. Dear friends, both of these states have to be marked and remembered. We have to see where our distractions are, and where we are being pulled away.","Once, at Ramanashram, thieves broke in. An ashram, too, can be entered by thieves. This was a scene that really happened. Bhagavan Sri Ramana Maharshi was there. That night the thieves came. What would an ashram hold? A few articles of worship, and fruits that people had brought. The thieves had their own purpose, their own intention, their own sankalpa. They became upset. In a great anger they began to beat people. They got ready to strike Bhagavan with sticks.","He remained in mauna, silence. The disciples cried out that this should not be done to Swami, and in anger they were going at the thieves. Ramana Maharshi said: they are doing their dharma. Our dharma is to remain in silence, with patience, and in peace. They will take what they have come to take. Why should we lay hands on them? The thieves took the fruits, and whatever else was there, and left.","Afterwards he said that the greatest thief of all is the mind. It kidnaps your joy and, in that very moment, carries it away. It goes on creating sorrow. Catch that thief. The others are petty thieves. This is how a knower of Brahman sees: with the eye of the Atman. How such a person lives on the physical plane is what he was showing."]$d4ens8json$::jsonb,
  4
from public.days d
join public.series s on s.id = d.series_id
where s.slug = 'devi-navaratrula-jnanam' and d.day_number = 4 and d.language = 'en'
