insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  'e42f0eb7-7d71-4ddd-affd-e6102246c98e'::uuid,
  d.id,
  10,
  $d5ens10title$Tripura Sundari · Ocean of Compassion$d5ens10title$,
  $d5ens10json$["Wonderful, friends. Let us hear a fine chant from Harika madam. In Devi Navaratri it is very beautiful: a stuti of the Devi, of the Mother, of that Parashakti. Harika madam sang of Tripura Sundari. Thank you, Harika madam. Tripura Sundari ma, dayasagarima — Mother Tripura Sundari, ocean of compassion. What abides in her is karuna, daya. Tripura Sundari means she who is in the three cities, the three puras: our Atman, the supreme principle of Paramatma. She herself dwells in the three puras. The quality of compassion in her, the daya — there is nothing that Shakti cannot do. For that Shakti nothing is impossible.","One must surrender to that Shakti. We give a name and a form and say ‘our Devi Mother.’ Actually, when we are sitting in meditation, we have to become surrendered to the Shakti. The Shakti knows. She is a mother-power of great compassion. The chant is the recognition of that, and the practice is the surrender."]$d5ens10json$::jsonb,
  2
