insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  '3f137a56-eb8f-41fd-acf1-03013fece1ce'::uuid,
  d.id,
  8,
  $d8ens8title$Devi Samarpan · The Practice$d8ens8title$,
  $d8ens8json$["Even if one asks Lord Rama or a great sage about rebirth and karma, the answer from the highest state is: ‘There is no rebirth, there is no karma — you only think there is.’ That is the vision from Turiya. But since most of us have not yet reached that plane, the practices remain necessary.","Therefore, the Sapta Jnana Bhumikas are a valuable structured reference for every sadhaka.","Now let us do Devi Samarpan once again. Sit comfortably. Devi Samarpan means offering oneself to the Mother — to the Kundalini Shakti who is already present within.","With the feeling of surrender (traditionally associated with the left nostril in this lineage), we offer the body, the breath, the thoughts, and the sense of ‘I’ to Her. Whatever arises — restlessness, emotion, or silence — is offered without holding anything back.","There is no need to reach a special state first. The offering itself is the practice. Even the inability to offer fully can be offered.","Remain in this offering for a few minutes. Let the breath be natural. Let the attention rest in the heart or at the crown, as feels natural.","When the mind wanders, gently bring it back by renewing the sense of offering. No force is required.","At the end of the practice, remain quiet for a moment. Then slowly open the eyes. The effect of the offering continues."]$d8ens8json$::jsonb,
  2
