insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  '09adf267-629f-4e21-adb0-3992107f5dd6'::uuid,
  d.id,
  10,
  $d8ens10title$Closing · Upcoming Programmes$d8ens10title$,
  $d8ens10json$["Thank you, friends. Tomorrow we will meet again early in the morning at 5 a.m. If everyone shares briefly, more people will get the chance to speak, and we can all hear one another’s experiences.","We will also meet in person at the end of this month (24–25) at the Quantum Life University campus for the One Maitriya programme. There is also a special two-day residential programme exclusively for doctors on ‘Inner Child – Pregnancy to Birth and Holistic Well-being,’ conducted by Dr. Newton and Dr. Lakshmi. Limited seats are available. Those who know doctors may share the information. Contact: 9849492098.","There are many more programmes coming, including the Soulco Transformation programme, which will conclude with the celebration of Dr. Newton’s birthday on Kartika Purnima. Everyone is welcome to join with family and friends.","Until tomorrow morning, let us spend more time in sadhana. The effect of today’s teaching and practice will continue to unfold.","Thank you once again for your presence and sincerity. May the Mother’s grace remain with all of us.","Om. We will meet tomorrow at 5 a.m."]$d8ens10json$::jsonb,
