insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  '8763cac6-a352-406c-af14-0683fa901d07'::uuid,
  d.id,
  2,
  $d9ens2title$Welcome · The Last Day of Navaratri$d9ens2title$,
  $d9ens2json$["Welcome back, everyone. We have come to the ninth day, the last day of this Navaratri. Tomorrow is the Dussehra celebration. For us, though, every day is a celebration, because we begin the day with wonderful knowledge.","Today too, let us welcome Brahmarshi Chakravarti Dr. Newton Kondaveti. Everyone on Zoom, please turn your cameras on, and with a smile let us welcome Sir. Thank you, Sir. Over to you.","Good morning, my dear friends of Jnanodayam. I trust that all of you have been practising beautifully through these Navaratri days. It is with that very sankalpa that we celebrate this festival in India. We do it every year. For these nine days we dedicate ourselves. We do it in order to understand Devi Shakti, to go completely near that Shakti, to connect with it, and to fill ourselves with it. Every year we do this. In every practice, and in every meditation, we keep coming to know many things."]$d9ens2json$::jsonb,
  1
