insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  'ca7d0f93-ecd4-4900-a8e0-98fba0467c77'::uuid,
  d.id,
  7,
  $d9ens7title$The Lotus in the Mud$d9ens7title$,
  $d9ens7json$["To speak of this, a Guru took his disciple to a pond. There was so much mud there. And there some lotuses, these lotus flowers, had opened and were beautiful. Wonderful. A pink lotus, a red lotus, a white lotus, a yellow lotus. So many lotus flowers, wonderful, all through that place. And there was mud everywhere. He asked, what do you see?","The disciple thought, why has the Guru brought me here? What is he showing me? He understood what he was meant to learn. We can put our focus on the mud and think that it is all mud. But we can also enjoy the lotus flower, that wonderfully opened flower pouring out its light, and look at it. The feeling can also arise in us that the lotus came because of this mud. This very mud gave all the nourishment for the lotus to be. Our situations, our hard situations, the stressful situation, have moulded us, shaped us, and made us, wonderfully, into people of knowledge. We become able to appreciate that."]$d9ens7json$::jsonb,
  1
