insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  '316bc1f9-6ae2-483c-a036-b05c5a98390c'::uuid,
  d.id,
  13,
  $d9ens13title$Devi Samarpan · Bowing Down$d9ens13title$,
  $d9ens13json$["Friends, now let us bow down to that Mother. This is the Devi Samarpan we do each day. Today is the last day. Tomorrow is only the celebration. How we do it is this. We take the Lakshmi mudra. If we place the left foot over the right foot, it gives more place to Shakti. Then we close the right nostril, and through the left nostril, our Chandra nadi, we take nine breaths inward. Nine inhalations. Take them slowly. Do not draw too much in. Then we hold, in a namaskara mudra. Leave a little gap. Hold, with one feeling. The feeling of surrender. Sharanagati. Bowing down. The feeling that before that Mother we are always little children. Let us bow down, and bow down by dropping our arrogance, the ego.","To drop all of that, bend the head completely down, as far as you are able, until it touches, and hold there. Hold the breath, and nine times, inwardly, we repeat Shreem. Shreem, Shreem, Shreem, Shreem, Shreem, Shreem, Shreem, Shreem, Shreem. Nine times we pronounce it within. During this time, let us feel that we are offering in this way both to our own mother and to the Mother of the world. Then, in the natural way, we bring the cells back to their own state. Let us do it nine times, friends. Those who still have it to complete, please continue.","The feeling is important. The feeling of offering. The Mother of the world is in us as Shakti. We must connect with that Shakti. It must be a complete surrender. Through Harika Madam, let us listen to a beautiful hymn of this Devi Shakti, the Mother of the world."]$d9ens13json$::jsonb,
  2
