insert into public.sections (id, day_id, section_order, title, content, minutes)
select
  '6ed8ec86-a244-4e6f-a8aa-8650d3a29c1c'::uuid,
  d.id,
  17,
  $d9ens17title$Closing · Vijayadashami, and Meeting Again$d9ens17title$,
  $d9ens17json$["It is half past seven. Tomorrow is the Vijayadashami celebration. At that time let us share all the rest. There is much to share. As part of tomorrow’s celebration, let us share. Thank you so much, Sir, for the time, for everything.","Friends, let us meet tomorrow morning at five. And in person, on the 24th and 25th, there is also the One Maitriya programme. On that day let us all meet here at Quantum Life University. Sir and Madam will be present. To be here in their presence, in that energy, to meditate, to connect with the plants in the gardens. It is a great opportunity. Do not miss it.","And the celebration of Dr. Newton’s birthday, and the annual day of Quantum Life University, falls this time on 24 November, on Kartika Purnima. On that day, at Quantum Life University, let all of us hold a Jnanodayam reunion. It will be an amazing opportunity. All of us should meet in person. This is an invitation to everyone who attends Jnanodayam, and to every person you know, your friends. Anyone may come. You are most welcome.","Thank you so much. And let us meet tomorrow morning."]$d9ens17json$::jsonb,
